def _scenario(id, opening, context, followup, correction, multi_intent, reflection, rubric):
    return dict(id=id, opening=opening, context=context, followup=followup,
                correction=correction, multi_intent=multi_intent, reflection=reflection,
                rubric=rubric, role="student", risk="safe")


